import java.io.*;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;

/**
 * Minimal root-cause analyzer that sends a truncated build log to OpenRouter and
 * writes the model's reply to an output file.
 *
 * Usage:
 *   javac RcaAnalyzer.java
 *   OPENROUTER_MODEL=<model> java RcaAnalyzer <log-file> <output-file> <openrouter_api_key>
 *
 * Notes:
 * - This is intentionally small and dependency-free (uses java.net.http available in Java 11+).
 * - The program truncates the input log to roughly the last N characters to keep the prompt size reasonable.
 */
public class RcaAnalyzer {
    private static final int MAX_LOG_CHARS = 32000; // last N chars
    private static final String OPENROUTER_URL = "https://openrouter.ai/api/v1/chat/completions";
    private static final String DEFAULT_MODEL = "deepseek/deepseek-r1-0528:free"; // fallback model

    public static void main(String[] args) throws Exception {
        if (args.length < 4) {
            System.err.println("Usage: java RcaAnalyzer <log-file> <output-file> <openrouter_key> <openrouter_model>");
            System.err.println("Optional environment variable: OPENROUTER_MODEL to override the model (e.g. 'gpt-4o-mini')");
            System.exit(2);
        }
        Path logPath = Path.of(args[0]);
        Path outPath = Path.of(args[1]);
        String apiKey = args[2];
        String model = args[3];

        if (!Files.exists(logPath)) {
            System.err.println("Log file not found: " + logPath);
            System.exit(3);
        }

        // Read model from environment (if provided), otherwise use default
        if (model == null || model.isBlank()) {
            model = System.getenv("OPENROUTER_MODEL");
        }
        if (model == null || model.isBlank()) {
            model = DEFAULT_MODEL;
        }

        String log = Files.readString(logPath, StandardCharsets.UTF_8);
        String trimmed = trimToLast(log, MAX_LOG_CHARS);

        String prompt = buildPrompt(trimmed);

        String requestBody = buildRequestBody(model, prompt);

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(OPENROUTER_URL))
                .timeout(Duration.ofSeconds(120))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + apiKey)
                .header("X-Title", "Test")
                .POST(HttpRequest.BodyPublishers.ofString(requestBody, StandardCharsets.UTF_8))
                .build();

        HttpResponse<String> resp = client.send(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
        String analysis;
        if (resp.statusCode() >= 200 && resp.statusCode() < 300) {
            analysis = parseOpenRouterResponse(resp.body());
        } else {
            analysis = "[ERROR] OpenRouter API returned status " + resp.statusCode() + "\n" + resp.body();
        }

        String header = "Root Cause Analysis (generated by OpenRouter)\n" +
                "===========================================\n\n";
        Files.writeString(outPath, header + analysis, StandardCharsets.UTF_8);
        System.out.println("Wrote analysis to: " + outPath.toAbsolutePath());
    }

    private static String trimToLast(String s, int maxChars) {
        if (s == null) return "";
        if (s.length() <= maxChars) return s;
        return "...TRUNCATED TO LAST " + maxChars + " CHARS...\n" + s.substring(s.length() - maxChars);
    }

    private static String buildPrompt(String logSnippet) {
        StringBuilder sb = new StringBuilder();
        sb.append("You are a software engineering assistant specialized in CI build failures.\n");
        sb.append("Analyze the following Maven build log and provide:\n");
        sb.append("1) A concise root cause hypothesis (1-3 bullets).\n");
        sb.append("2) Top 3 actionable remediation steps (short commands or config hints).\n");
        sb.append("3) Quick checks to validate the fix.\n");
        sb.append("Be concise and prioritize the most likely causes. If logs are insufficient, list additional data to collect.\n\n");
        sb.append("BUILD LOG SNIPPET:\n```");
        sb.append(logSnippet);
        sb.append("\n```\n\n");
        sb.append("Provide the answer in plain text, using headings and short bullet lists.\n");
        return sb.toString();
    }

    private static String buildRequestBody(String model, String prompt) {
        // Build a minimal OpenRouter chat/completion payload. Adjust if your OpenRouter instance expects different format.
        return "{"
                + "\"model\":\"" + model + "\","
                + "\"messages\": [{\"role\":\"user\",\"content\":\"" + escapeJson(prompt) + "\"}],"
                + "\"temperature\":0.2"
                + "}";
    }

    private static String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private static String parseOpenRouterResponse(String body) {
        // OpenRouter returns a JSON response; this minimal parser searches for a plausible text field.
        // Example: {"id":...,"choices":[{"message":{"content":{"type":"output_text","content":"..."}}}]}
        // We'll attempt simple heuristics to extract the longest quoted text chunk.
        try {
            // naive: find "content" occurrences
            int idx = body.indexOf("\"content\"");
            if (idx >= 0) {
                int start = body.indexOf('"', idx + 10);
                if (start >= 0) {
                    int end = body.indexOf('"', start + 1);
                    if (end > start) {
                        // fallback: but this gets only short fragments; instead try to locate output_text content
                    }
                }
            }
            // More robust: attempt to find the longest string between quotes (not perfect, but okay for small outputs)
            String longest = "";
            int i = 0;
            while (i < body.length()) {
                int a = body.indexOf('"', i);
                if (a < 0) break;
                int b = body.indexOf('"', a + 1);
                if (b < 0) break;
                String cand = body.substring(a + 1, b);
                if (cand.length() > longest.length()) longest = cand;
                i = b + 1;
            }
            if (!longest.isBlank()) {
                return longest.replace("\\n", "\n").replace("\\\"", "\"");
            }
        } catch (Exception e) {
            // ignore
        }
        // fallback: return raw body
        return body;
    }
}
